import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-not-found',
  templateUrl: './not-found.component.html',
  styleUrls: ['./not-found.component.css']
})
export class NotFoundComponent {

    constructor(
      private jobService: JobService,
      private compService: CompanyService,
      private jobSeekerService: JobseekerService,
      private router: Router
    ) {}

    jobs: Job[] = [];
    companies: Company[] = [];

    isLoggedIn = false;
    initials = '';
    profileRoute = '/';

    ngOnInit() {

      this.isLoggedIn = !!localStorage.getItem('token');

      if (this.isLoggedIn) {

        const role = localStorage.getItem('role');
        const id = Number(localStorage.getItem('id'));

        if (role === 'COMPANY') {

          this.profileRoute = '/company-dashboard';

          this.compService.getCompanyById(id).subscribe((company) => {
            this.initials = company.companyName
              .split(' ')
              .map(x => x[0])
              .join('')
              .substring(0, 2)
              .toUpperCase();
          });

        } else {

          this.profileRoute = '/jobseeker-dashboard';

          this.jobSeekerService.getJobSeekerById(id).subscribe((seeker) => {
            this.initials = (seeker.firstName.charAt(0) + seeker.lastName.charAt(0)).toUpperCase();
          });

        }
      }

      this.getAllJobs();
      this.getAllCompanies();
    }

    getAllJobs() {
      this.jobService.getAllJobs().subscribe((res) => {
        this.jobs = res;
      });
    }

    getAllCompanies() {
      this.compService.getAllCompanies().subscribe((res) => {
        this.companies = res;
      });
    }

    logout(){
      localStorage.clear();
      this.router.navigate(['/']);
    }



}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Not Found · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav">
  <div class="wrap">
    <a routerLink="/" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links">
      <a routerLink="/alljobs">Find Jobs</a>
      <a routerLink="/all-companies">Companies</a>
    </nav>
    <!-- Not Logged In -->
<div class="nav-actions" *ngIf="!isLoggedIn">
  <a routerLink="/login" class="btn btn-ghost-dark btn-sm">Log in</a>
  <a routerLink="/register" class="btn btn-primary btn-sm">Sign up</a>
</div>

<!-- Logged In -->
<div class="nav-actions" *ngIf="isLoggedIn">
  <div class="avatar" [routerLink]="profileRoute">
    {{ initials }}
  </div>
  <button class="btn btn-ghost-dark btn-sm" (click)="logout()">
        Logout
      </button>
</div>

  </div>
</header>
<div class="err-wrap">
  <div class="err-code">404</div>
  <h2 style="margin-top:12px;font-size:24px;">This page went unlisted.</h2>
  <p class="muted" style="margin-top:10px;max-width:380px;">The job, company or page you're looking for isn't here anymore.</p>
  <a routerLink="/" class="btn btn-primary" style="margin-top:24px;">Back to home</a>
</div>
<footer class="site-footer">
  <div class="wrap">
    <span>© 2026 HireHub</span>
    <span class="mono-label" style="color:var(--muted-lt)">com.aitrich.JobPortalSystem</span>
  </div>
</footer></div>
</body>
</html>
